package com.bank.backupstrategy;
import com.bank.backupstrategy.model.BackupPolicy;
import com.bank.backupstrategy.service.BackupOrchestrator;
import java.util.logging.*;

public class StrategyDemo {
    public static void main(String[] args) {
        BackupPolicy policy = new BackupPolicy(5, 60, 7, 84);  // RPO 5s, RTO 60m, 7y monthly
        BackupOrchestrator orch = new BackupOrchestrator(policy);
        orch.runDailyFull();
        orch.archiveWal();
        orch.enforceRetention();
        orch.restoreDrill();
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
